// Verifies that setting the value does not corrupt the remoteness field.
TEST(ArrayDbRecordTest, SetValuePreservesRemoteness) {
    Record rec = 0;
    RecordSetValueRemoteness(&rec, kLose, 42);

    RecordSetValue(&rec, kWin);

    EXPECT_EQ(RecordGetValue(&rec), kWin) << "Value should be updated to kWin.";
    EXPECT_EQ(RecordGetRemoteness(&rec), 42)
        << "Remoteness should remain 42 after changing only the value.";
}

