// ============================== RecordMaximize ==============================

// Verifies that a strictly greater candidate replaces the current record.
TEST(ArrayDbRecordTest, MaximizeReplacesWhenCandidateGreater) {
    Record rec = 0;
    RecordSetValueRemoteness(&rec, kLose, 0);

    bool replaced =
        RecordMaximize(&rec, kWin, 10, CompareByValueThenRemoteness);

    EXPECT_TRUE(replaced) << "Should return true when candidate is greater.";
    EXPECT_EQ(RecordGetValue(&rec), kWin)
        << "Value should be updated to the candidate's value.";
    EXPECT_EQ(RecordGetRemoteness(&rec), 10)
        << "Remoteness should be updated to the candidate's remoteness.";
}

// Verifies that a strictly smaller candidate does not replace the current
// record.
TEST(ArrayDbRecordTest, MaximizeKeepsWhenCandidateSmaller) {
    Record rec = 0;
    RecordSetValueRemoteness(&rec, kWin, 10);

    bool replaced =
        RecordMaximize(&rec, kLose, 0, CompareByValueThenRemoteness);

    EXPECT_FALSE(replaced) << "Should return false when candidate is smaller.";
    EXPECT_EQ(RecordGetValue(&rec), kWin) << "Value should remain unchanged.";
    EXPECT_EQ(RecordGetRemoteness(&rec), 10)
        << "Remoteness should remain unchanged.";
}

// Verifies that an equal candidate does not replace the current record.
TEST(ArrayDbRecordTest, MaximizeKeepsWhenEqual) {
    Record rec = 0;
    RecordSetValueRemoteness(&rec, kTie, 5);

    bool replaced = RecordMaximize(&rec, kTie, 5, CompareByValueThenRemoteness);

    EXPECT_FALSE(replaced) << "Should return false when candidate is equal.";
    EXPECT_EQ(RecordGetValue(&rec), kTie) << "Value should remain unchanged.";
    EXPECT_EQ(RecordGetRemoteness(&rec), 5)
        << "Remoteness should remain unchanged.";
}

// Verifies that a candidate with the same value but higher remoteness replaces
// the record (using the lexicographic comparator).
TEST(ArrayDbRecordTest, MaximizeReplacesOnRemotenessAlone) {
    Record rec = 0;
    RecordSetValueRemoteness(&rec, kWin, 3);

    bool replaced = RecordMaximize(&rec, kWin, 7, CompareByValueThenRemoteness);

    EXPECT_TRUE(replaced)
        << "Should return true when candidate has higher remoteness.";
    EXPECT_EQ(RecordGetValue(&rec), kWin) << "Value should remain kWin.";
    EXPECT_EQ(RecordGetRemoteness(&rec), 7)
        << "Remoteness should be updated to 7.";
}

// Verifies that a candidate with the same value but lower remoteness does not
// replace the record.
TEST(ArrayDbRecordTest, MaximizeKeepsOnRemotenessAlone) {
    Record rec = 0;
    RecordSetValueRemoteness(&rec, kWin, 7);

    bool replaced = RecordMaximize(&rec, kWin, 3, CompareByValueThenRemoteness);

    EXPECT_FALSE(replaced)
        << "Should return false when candidate has lower remoteness.";
    EXPECT_EQ(RecordGetValue(&rec), kWin) << "Value should remain kWin.";
    EXPECT_EQ(RecordGetRemoteness(&rec), 7) << "Remoteness should remain 7.";
}

// Verifies that RecordMaximize correctly delegates ordering to the comparator
// by using a reversed comparator where lower values are "greater".
TEST(ArrayDbRecordTest, MaximizeWithAlternativeComparator) {
    Record rec = 0;
    RecordSetValueRemoteness(&rec, kWin, 10);

    // With CompareReversed, (kLose, 0) is considered "greater" than (kWin, 10).
    bool replaced = RecordMaximize(&rec, kLose, 0, CompareReversed);

    EXPECT_TRUE(replaced)
        << "Should return true when candidate is greater under the reversed "
           "comparator.";
    EXPECT_EQ(RecordGetValue(&rec), kLose)
        << "Value should be updated to kLose under the reversed comparator.";
    EXPECT_EQ(RecordGetRemoteness(&rec), 0)
        << "Remoteness should be updated to 0 under the reversed comparator.";
}

// ==================== RecordDecrementNumUndecidedChildren ====================

// Verifies that decrementing from a positive count works correctly.
TEST(ArrayDbRecordTest, DecrementFromPositiveCount) {
    Record rec = 0;
    RecordSetValueRemoteness(&rec, kUndecided, 5);

    int old_count = RecordDecrementNumUndecidedChildren(&rec);

    EXPECT_EQ(old_count, 5) << "Should return the count before decrementing.";
    EXPECT_EQ(RecordGetNumUndecidedChildren(&rec), 4)
        << "Count should be decremented by one.";
}

// Verifies that decrementing from 1 reaches zero.
TEST(ArrayDbRecordTest, DecrementToZero) {
    Record rec = 0;
    RecordSetValueRemoteness(&rec, kUndecided, 1);

    int old_count = RecordDecrementNumUndecidedChildren(&rec);

    EXPECT_EQ(old_count, 1) << "Should return 1 (count before decrementing).";
    EXPECT_EQ(RecordGetNumUndecidedChildren(&rec), 0)
        << "Count should be 0 after decrementing from 1.";
}

// Verifies that decrementing when the count is already zero is a no-op.
TEST(ArrayDbRecordTest, DecrementWhenAlreadyZero) {
    Record rec = 0;
    RecordSetValueRemoteness(&rec, kUndecided, 0);

    int old_count = RecordDecrementNumUndecidedChildren(&rec);

    EXPECT_EQ(old_count, 0)
        << "Should return 0 when the count was already zero.";
    EXPECT_EQ(RecordGetNumUndecidedChildren(&rec), 0)
        << "Count should remain 0.";
}

// Verifies that decrementing is a no-op when value is not kUndecided (kLose).
TEST(ArrayDbRecordTest, DecrementWhenNotUndecidedLose) {
    Record rec = 0;
    RecordSetValueRemoteness(&rec, kLose, 5);

    int result = RecordDecrementNumUndecidedChildren(&rec);

    EXPECT_EQ(result, 0) << "Should return 0 when value is not kUndecided.";
    EXPECT_EQ(RecordGetValue(&rec), kLose) << "Value should remain kLose.";
    EXPECT_EQ(RecordGetRemoteness(&rec), 5)
        << "Remoteness should remain unchanged.";
}

// Verifies that decrementing is a no-op when value is not kUndecided (kWin).
TEST(ArrayDbRecordTest, DecrementWhenNotUndecidedWin) {
    Record rec = 0;
    RecordSetValueRemoteness(&rec, kWin, 10);

    int result = RecordDecrementNumUndecidedChildren(&rec);

    EXPECT_EQ(result, 0) << "Should return 0 when value is not kUndecided.";
    EXPECT_EQ(RecordGetValue(&rec), kWin) << "Value should remain kWin.";
    EXPECT_EQ(RecordGetRemoteness(&rec), 10)
        << "Remoteness should remain unchanged.";
}

// Verifies that successive decrements correctly drain the count to zero.
TEST(ArrayDbRecordTest, DecrementSuccessivelyToZero) {
    Record rec = 0;
    RecordSetValueRemoteness(&rec, kUndecided, 3);

    EXPECT_EQ(RecordDecrementNumUndecidedChildren(&rec), 3)
        << "First decrement should return 3.";
    EXPECT_EQ(RecordDecrementNumUndecidedChildren(&rec), 2)
        << "Second decrement should return 2.";
    EXPECT_EQ(RecordDecrementNumUndecidedChildren(&rec), 1)
        << "Third decrement should return 1.";
    EXPECT_EQ(RecordDecrementNumUndecidedChildren(&rec), 0)
        << "Fourth decrement should return 0 (count was already zero).";
    EXPECT_EQ(RecordGetNumUndecidedChildren(&rec), 0)
        << "Final count should be 0.";
}

