// ======================== Cross-function Integration ========================

// Verifies that a zero-initialized Record reads as kUndecided with remoteness
// zero, a useful invariant that does not peek at the internal bit layout.
TEST(ArrayDbRecordTest,
     ZeroInitializedRecordHasUndecidedValueAndZeroRemoteness) {
    Record rec = 0;

    EXPECT_EQ(RecordGetValue(&rec), kUndecided)
        << "A zero-initialized Record should have value kUndecided.";
    EXPECT_EQ(RecordGetRemoteness(&rec), 0)
        << "A zero-initialized Record should have remoteness 0.";
}

// Verifies the interplay between SetValueRemoteness and
// GetNumUndecidedChildren.
TEST(ArrayDbRecordTest, SetValueRemotenessThenGetNumUndecidedChildren) {
    Record rec = 0;
    RecordSetValueRemoteness(&rec, kUndecided, 3);

    EXPECT_EQ(RecordGetNumUndecidedChildren(&rec), 3)
        << "NumUndecidedChildren should match remoteness when value is "
           "kUndecided.";

    RecordSetValue(&rec, kWin);

    EXPECT_EQ(RecordGetNumUndecidedChildren(&rec), 0)
        << "NumUndecidedChildren should be 0 once value is no longer "
           "kUndecided.";
}

// Verifies that decrementing followed by clearing works correctly together.
TEST(ArrayDbRecordTest, DecrementThenClear) {
    Record rec = 0;
    RecordSetValueRemoteness(&rec, kUndecided, 5);

    int after_dec = RecordDecrementNumUndecidedChildren(&rec);
    EXPECT_EQ(after_dec, 5) << "Decrement should return the old count of 5.";
    EXPECT_EQ(RecordGetNumUndecidedChildren(&rec), 4)
        << "Count should be 4 after one decrement.";

    int after_clear = RecordClearNumUndecidedChildren(&rec);
    EXPECT_EQ(after_clear, 4) << "Clear should return the old count of 4.";
    EXPECT_EQ(RecordGetNumUndecidedChildren(&rec), 0)
        << "Count should be 0 after clearing.";
}

// Verifies that RecordMaximize results are readable through the getters.
TEST(ArrayDbRecordTest, MaximizeThenGetFields) {
    Record rec = 0;
    RecordSetValueRemoteness(&rec, kLose, 0);

    RecordMaximize(&rec, kWin, 50, CompareByValueThenRemoteness);

    EXPECT_EQ(RecordGetValue(&rec), kWin)
        << "Value should be kWin after maximize.";
    EXPECT_EQ(RecordGetRemoteness(&rec), 50)
        << "Remoteness should be 50 after maximize.";
}

// Verifies a round-trip set-and-get for every legal Value, holding remoteness
// constant to confirm field isolation.
TEST(ArrayDbRecordTest, SetAllValuesRoundTrip) {
    constexpr int kFixedRemoteness = 99;
    const Value kAllValues[] = {kUndecided, kLose, kDraw, kTie, kWin};

    for (Value val : kAllValues) {
        Record rec = 0;
        RecordSetValueRemoteness(&rec, val, kFixedRemoteness);

        EXPECT_EQ(RecordGetValue(&rec), val)
            << "Round-trip value mismatch for Value " << val << ".";
        EXPECT_EQ(RecordGetRemoteness(&rec), kFixedRemoteness)
            << "Remoteness should remain " << kFixedRemoteness
            << " regardless of which Value is set.";
    }
}
